import { readFileSync } from "node:fs";
import type { ConfigEnv, UserConfig } from "vite";
import baseConfig from "./vite.config.ts";

// `npm run test:gate`: same settings as `npm test`, but only the files in tools/test/test-gate.list
// (generated by tools/test/generateTestGate.ts; rule in docs/cln240-test-gate.md).
const gateFiles = readFileSync("tools/test/test-gate.list", "utf8").split("\n").filter(Boolean);

export default async (env: ConfigEnv): Promise<UserConfig> => {
  const base = typeof baseConfig === "function" ? await baseConfig(env) : await baseConfig;
  return { ...base, test: { ...base.test, include: gateFiles } } as UserConfig;
};
